import java.io.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream is = System.in;

    static int readByte() throws IOException {
        if (ptr == len) { len = is.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static String next() throws IOException {
        int c = readByte();
        while (c != -1 && c <= ' ') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = readByte(); }
        return sb.toString();
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c != '-' && (c < '0' || c > '9')) c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = readByte(); }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        nextLong(); // N is not needed
        int q = (int) nextLong();
        nextLong(); // S = 2
        long[] l = new long[q], r = new long[q];
        for (int i = 0; i < q; i++) { l[i] = nextLong(); r[i] = nextLong(); }
        long k = nextLong(), answer = k;
        // ranges never overlap: the one covering K reverses it, so K holds soldier l + r - K
        for (int i = 0; i < q; i++) if (l[i] <= k && k <= r[i]) answer = l[i] + r[i] - k;
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	next := func() int64 {
		sc.Scan()
		v, _ := strconv.ParseInt(sc.Text(), 10, 64)
		return v
	}
	next() // N is not needed
	q := int(next())
	next() // S = 2
	l := make([]int64, q)
	r := make([]int64, q)
	for i := 0; i < q; i++ {
		l[i], r[i] = next(), next()
	}
	k := next()
	answer := k
	// ranges never overlap: the one covering K reverses it, so K holds soldier l + r - K
	for i := 0; i < q; i++ {
		if l[i] <= k && k <= r[i] {
			answer = l[i] + r[i] - k
		}
	}
	fmt.Println(answer)
}
